// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(
        address baseTokenArg,
        address nftArg,
        uint128 virtualBase,
        uint128 virtualNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoyalties
    ) public {
        vm.assume(baseTokenArg != address(0));
        vm.assume(virtualNft > virtualBase); // keep admissible: buy/sell quotes well-defined
        c.initialize(
            baseTokenArg,
            nftArg,
            virtualBase,
            virtualNft,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoyalties
        );
        assertTrue(c.baseToken() == baseTokenArg);
    }
}
